const { readFileSync, existsSync } = await import('node:fs');
if (!globalThis.input || !globalThis.input.doc_path) {
  throw new Error('Missing doc_path input');
}
if (!existsSync(globalThis.input.doc_path)) {
  throw new Error('Input file does not exist');
}
globalThis.docBuffer = readFileSync(globalThis.input.doc_path);

const mod = await import('office-to-pdf');
const toPdf = mod.default || mod;
globalThis.pdfBuffer = await toPdf(globalThis.docBuffer);

if (!globalThis.pdfBuffer) {
  throw new Error('PDF conversion failed');
}
const result = { pdf_base64: globalThis.pdfBuffer.toString('base64') };
console.log(JSON.stringify(result));
